    for k in inventory:
        inv[k] = {"price": inventory[k]["price"], "stock": inventory[k]["stock"]}
    for o in orders:
        ok = True
        reason = None
        total = 0.0
        for it in o["items"]:
            if it["sku"] not in inv:
                ok = False
                reason = "unknown sku " + it["sku"]
                break
            if it["qty"] <= 0:
                ok = False
                reason = "bad qty"
                break
            if inv[it["sku"]]["stock"] < it["qty"]:
                ok = False
                reason = "out of stock " + it["sku"]
                break
            total = total + inv[it["sku"]]["price"] * it["qty"]
